  UNIQUE KEY `uq_appointment_slot_claim_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_appointment_slot_claim_appointment` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`appointment_id`),
  CONSTRAINT `fk_appointment_slot_claim_appointment_slot` FOREIGN KEY (`appointment_slot_id`) REFERENCES `appointment_slot` (`appointment_slot_id`),
  CONSTRAINT `fk_appointment_slot_claim_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_appointment_slot_claim_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_appointment_slot_claim_1` CHECK (`claim_reason` IN ('initial','reschedule')),
  CONSTRAINT `ck_appointment_slot_claim_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Appointment x Slot. Trigger repeats the live-claim check (R3.6).';

CREATE TABLE `visit` (
  `visit_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `patient_id` BIGINT UNSIGNED NOT NULL,
  `appointment_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `entry_type` VARCHAR(15) NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`visit_id`),
  UNIQUE KEY `uq_visit_1` (`appointment_id`),
  UNIQUE KEY `uq_visit_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_visit_patient` FOREIGN KEY (`patient_id`) REFERENCES `patient` (`patient_id`),
  CONSTRAINT `fk_visit_appointment` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`appointment_id`),
  CONSTRAINT `fk_visit_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_visit_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_visit_1` CHECK (`entry_type` IN ('appointment','walk_in','emergency')),
  CONSTRAINT `ck_visit_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Immutable parent of everything clinical/financial (R3.1).';

CREATE TABLE `visit_status_history` (
  `visit_status_history_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `visit_id` BIGINT UNSIGNED NOT NULL,
  `status_seq` SMALLINT NOT NULL,
  `status` VARCHAR(15) NOT NULL,
  `location_label` VARCHAR(60) NULL DEFAULT NULL,
  `reason` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`visit_status_history_id`),
  UNIQUE KEY `uq_visit_status_history_1` (`visit_id`, `status_seq`),
  UNIQUE KEY `uq_visit_status_history_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_visit_status_history_visit` FOREIGN KEY (`visit_id`) REFERENCES `visit` (`visit_id`),
  CONSTRAINT `fk_visit_status_history_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_visit_status_history_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_visit_status_history_1` CHECK (`status` IN ('arrived','waiting','with_doctor','lab','pharmacy','billing','discharged')),
  CONSTRAINT `ck_visit_status_history_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Weak on visit. Latest row = current status/location. No beds.';

CREATE TABLE `family_link` (
  `family_link_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `visit_id` BIGINT UNSIGNED NOT NULL,
  `attendant_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `token_hash` CHAR(64) NOT NULL,
  `second_factor_kind` VARCHAR(17) NOT NULL,
  `printed_code_hash` CHAR(64) NULL DEFAULT NULL,
  `expires_at` DATETIME(3) NOT NULL,
  `consent_note` VARCHAR(300) NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`family_link_id`),
  UNIQUE KEY `uq_family_link_1` (`token_hash`),
  UNIQUE KEY `uq_family_link_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_family_link_visit` FOREIGN KEY (`visit_id`) REFERENCES `visit` (`visit_id`),
  CONSTRAINT `fk_family_link_patient_attendant` FOREIGN KEY (`attendant_id`) REFERENCES `patient_attendant` (`patient_attendant_id`),
  CONSTRAINT `fk_family_link_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_family_link_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_family_link_1` CHECK (`second_factor_kind` IN ('date_of_birth','printed_code')),
  CONSTRAINT `ck_family_link_2` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_family_link_3` CHECK ((second_factor_kind = 'printed_code') = (printed_code_hash IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Read-only tokenized link scoped to one visit (R11). Only hashes stored.';

CREATE TABLE `visit_doctor_assignment` (
  `visit_doctor_assignment_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `visit_id` BIGINT UNSIGNED NOT NULL,
  `doctor_staff_id` BIGINT UNSIGNED NOT NULL,
  `assignment_role` VARCHAR(13) NOT NULL DEFAULT 'attending',
  `reason` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`visit_doctor_assignment_id`),
  UNIQUE KEY `uq_visit_doctor_assignment_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_visit_doctor_assignment_visit` FOREIGN KEY (`visit_id`) REFERENCES `visit` (`visit_id`),
  CONSTRAINT `fk_visit_doctor_assignment_doctor_detail` FOREIGN KEY (`doctor_staff_id`) REFERENCES `doctor_detail` (`staff_id`),
  CONSTRAINT `fk_visit_doctor_assignment_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_visit_doctor_assignment_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_visit_doctor_assignment_1` CHECK (`assignment_role` IN ('attending','covering')),
  CONSTRAINT `ck_visit_doctor_assignment_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Attending / covering doctor of a visit.';

CREATE TABLE `link_access_log` (
  `link_access_log_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `family_link_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `token_fingerprint` VARCHAR(16) NOT NULL,
  `success` TINYINT(1) NOT NULL,
  `failure_reason` VARCHAR(60) NULL DEFAULT NULL,
  `source_context` VARCHAR(100) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`link_access_log_id`),
  UNIQUE KEY `uq_link_access_log_request_uuid` (`request_uuid`),
  KEY `ix_link_access_log_1` (`family_link_id`, `recorded_at`),
  CONSTRAINT `fk_link_access_log_family_link` FOREIGN KEY (`family_link_id`) REFERENCES `family_link` (`family_link_id`),
  CONSTRAINT `fk_link_access_log_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_link_access_log_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_link_access_log_1` CHECK (`success` IN (0,1)),
  CONSTRAINT `ck_link_access_log_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Every attempt, success or not (R11.4). Lockout derived from it.';

CREATE TABLE `short_stay_episode` (
  `short_stay_episode_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `visit_id` BIGINT UNSIGNED NOT NULL,
  `admission_reason` VARCHAR(300) NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`short_stay_episode_id`),
  UNIQUE KEY `uq_short_stay_episode_1` (`visit_id`),
  UNIQUE KEY `uq_short_stay_episode_2` (`short_stay_episode_id`, `visit_id`),
  UNIQUE KEY `uq_short_stay_episode_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_short_stay_episode_visit` FOREIGN KEY (`visit_id`) REFERENCES `visit` (`visit_id`),
  CONSTRAINT `fk_short_stay_episode_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_short_stay_episode_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_short_stay_episode_1` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Subtype of visit (S2). Extension/closure are separate events.';

CREATE TABLE `family_link_revocation` (
  `family_link_revocation_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `family_link_id` BIGINT UNSIGNED NOT NULL,
  `reason` VARCHAR(300) NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`family_link_revocation_id`),
  UNIQUE KEY `uq_family_link_revocation_1` (`family_link_id`),
  UNIQUE KEY `uq_family_link_revocation_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_family_link_revocation_family_link` FOREIGN KEY (`family_link_id`) REFERENCES `family_link` (`family_link_id`),
  CONSTRAINT `fk_family_link_revocation_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_family_link_revocation_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_family_link_revocation_1` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Instant revocation without touching the link.';

CREATE TABLE `short_stay_extension` (
  `short_stay_extension_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `short_stay_episode_id` BIGINT UNSIGNED NOT NULL,
  `approval_request_id` BIGINT UNSIGNED NOT NULL,
  `extended_until` DATETIME(3) NOT NULL,
  `reason` VARCHAR(300) NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`short_stay_extension_id`),
  UNIQUE KEY `uq_short_stay_extension_1` (`approval_request_id`),
  UNIQUE KEY `uq_short_stay_extension_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_short_stay_extension_short_stay_episode` FOREIGN KEY (`short_stay_episode_id`) REFERENCES `short_stay_episode` (`short_stay_episode_id`),
  CONSTRAINT `fk_short_stay_extension_approval_request` FOREIGN KEY (`approval_request_id`) REFERENCES `approval_request` (`approval_request_id`),
  CONSTRAINT `fk_short_stay_extension_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_short_stay_extension_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_short_stay_extension_1` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Approved extension beyond stay_limit_hours (R3.4).';

CREATE TABLE `short_stay_closure` (
  `short_stay_closure_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `short_stay_episode_id` BIGINT UNSIGNED NOT NULL,
  `reason` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`short_stay_closure_id`),
  UNIQUE KEY `uq_short_stay_closure_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_short_stay_closure_short_stay_episode` FOREIGN KEY (`short_stay_episode_id`) REFERENCES `short_stay_episode` (`short_stay_episode_id`),
  CONSTRAINT `fk_short_stay_closure_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_short_stay_closure_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_short_stay_closure_1` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Ends a short stay.';

CREATE TABLE `vitals_observation` (
  `vitals_observation_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `visit_id` BIGINT UNSIGNED NOT NULL,
  `observation_seq` INT NOT NULL,
  `short_stay_episode_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `observation_set_uuid` CHAR(36) NOT NULL,
  `observation_type` VARCHAR(17) NOT NULL,
  `numeric_value` DECIMAL(8,2) NULL DEFAULT NULL,
  `text_value` VARCHAR(100) NULL DEFAULT NULL,
  `unit` VARCHAR(20) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  `corrects_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`vitals_observation_id`),
  UNIQUE KEY `uq_vitals_observation_1` (`visit_id`, `observation_seq`),
  UNIQUE KEY `uq_vitals_observation_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_vitals_observation_visit` FOREIGN KEY (`visit_id`) REFERENCES `visit` (`visit_id`),
  CONSTRAINT `fk_vitals_observation_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_vitals_observation_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `fk_vitals_observation_vitals_observation` FOREIGN KEY (`corrects_id`) REFERENCES `vitals_observation` (`vitals_observation_id`),
  CONSTRAINT `fk_vitals_observation_short_stay_episode_c` FOREIGN KEY (`short_stay_episode_id`, `visit_id`) REFERENCES `short_stay_episode` (`short_stay_episode_id`, `visit_id`),
  CONSTRAINT `ck_vitals_observation_1` CHECK (`observation_type` IN ('bp_systolic','bp_diastolic','pulse','temperature','spo2','resp_rate','weight','height','blood_glucose','other')),
  CONSTRAINT `ck_vitals_observation_2` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_vitals_observation_3` CHECK (numeric_value IS NOT NULL OR text_value IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Weak on visit; one typed row per measurement (BP = two rows sharing observation_set_uuid).';
